-- ============================================================
-- Chef's Table SQL Portfolio Project — schema.sql
-- ============================================================
-- Run from the project root with:
--
--     duckdb chefs_table.duckdb < schema.sql
--
-- This creates the three tables and loads the synthetic CSVs
-- generated by generate_data.py (data/*.csv).
-- ============================================================

CREATE TABLE menu_items (
    item_id     INTEGER PRIMARY KEY,
    item_name   TEXT NOT NULL,
    category    TEXT NOT NULL,          -- appetizer / entree / bread / dessert / beverage
    unit_cost   DECIMAL(10,2) NOT NULL, -- cost per unit in dollars
    unit_price  DECIMAL(10,2) NOT NULL  -- menu price in dollars
);

-- One row per item per day.
CREATE TABLE inventory_log (
    log_id        INTEGER PRIMARY KEY,
    item_id       INTEGER NOT NULL REFERENCES menu_items(item_id),
    log_date      DATE NOT NULL,
    qty_received  INTEGER NOT NULL,     -- units delivered / prepped that day
    qty_used      INTEGER NOT NULL,     -- units sold
    qty_wasted    INTEGER NOT NULL      -- units tossed
);

-- One row per line item on a ticket.
CREATE TABLE sales (
    sale_id  INTEGER PRIMARY KEY,
    item_id  INTEGER NOT NULL REFERENCES menu_items(item_id),
    sale_ts  TIMESTAMP NOT NULL,
    qty      INTEGER NOT NULL,
    revenue  DECIMAL(10,2) NOT NULL
);

-- ---------------- Load the CSVs (run from the project root) ----------------
COPY menu_items    FROM 'data/menu_items.csv'    (HEADER, AUTO_DETECT TRUE);
COPY inventory_log FROM 'data/inventory_log.csv' (HEADER, AUTO_DETECT TRUE);
COPY sales         FROM 'data/sales.csv'         (HEADER, AUTO_DETECT TRUE);

-- Sanity checks
SELECT 'menu_items'    AS tbl, COUNT(*) AS rows FROM menu_items
UNION ALL
SELECT 'inventory_log' AS tbl, COUNT(*) AS rows FROM inventory_log
UNION ALL
SELECT 'sales'         AS tbl, COUNT(*) AS rows FROM sales
UNION ALL
SELECT 'date_range'    AS tbl, COUNT(DISTINCT log_date) AS rows FROM inventory_log;
